// Position whole hit rectangles, not just symbols. Dense rooms use a collision-free grid.
function layoutScene(){const scene=document.getElementById('scene');if(!scene)return;const W=scene.clientWidth,H=scene.clientHeight;
 scene.classList.remove('garden-dense');const buttons=[...scene.querySelectorAll('.mission-star')],n=buttons.length;scene.classList.toggle('compact-missions',n>6&&(H<730||W<370));if(!n){positionActor();positionCats();return;}
 const strip=scene.querySelector('.pinned-strip'),top=strip&&strip.children.length?strip.offsetTop+strip.offsetHeight+12:76;
 const bw=buttons[0].offsetWidth,bh=buttons[0].offsetHeight;
 const left=bw/2+12,right=W-bw/2-12,minY=top+bh/2,maxY=Math.max(minY,H-Math.min(180,H*.24)-bh/2);
 const maxCols=Math.max(1,Math.floor((W-20)/(bw+8))),cols=Math.min(maxCols,Math.max(1,Math.ceil(Math.sqrt(n*W/Math.max(1,maxY-minY+bh))))),rows=Math.ceil(n/cols);
 const positions=[];
 if(roomId==='garden'){
  const actor=scene.querySelector('#alba'),aw=actor?.offsetWidth||0,ah=actor?.offsetHeight||0;
  const face={left:W*.51-aw*.24,right:W*.51+aw*.24,top:H*.94-ah*.95,bottom:H*.94-ah*.53};
  let scattered=WLD.gardenPositions(buttons.map(b=>b.dataset.id),{W,H,bw,bh,minY,maxY:Math.max(minY,H-112-bh/2),day:E.dayKey(),face});
  if(!scattered){scene.classList.add('garden-dense');const sw=buttons[0].offsetWidth,sh=buttons[0].offsetHeight;scattered=WLD.gardenPositions(buttons.map(b=>b.dataset.id),{W,H,bw:sw,bh:sh,minY:top+sh/2,maxY:H-112-sh/2,day:E.dayKey(),face});}
  if(scattered){buttons.forEach((b,i)=>{b.style.left=scattered[i].x+'px';b.style.top=scattered[i].y+'px';});positionActor();positionCats();return;}
 }
 let hinted=n<=6;
 for(const b of buttons){const a=window.FairyLayout[b.dataset.id];if(!a){hinted=false;break;}const p={x:Math.max(left,Math.min(right,a[0]*W)),y:Math.max(minY,Math.min(maxY,a[1]*H))};if(positions.some(q=>Math.abs(q.x-p.x)<bw+8&&Math.abs(q.y-p.y)<bh+8)){hinted=false;break;}positions.push(p);}
 if(!hinted){positions.length=0;let bottom=Math.max(maxY,minY+(rows-1)*(bh+6));bottom=Math.min(H-75-bh/2,bottom);
  for(let i=0;i<n;i++){const row=Math.floor(i/cols),col=i%cols,count=Math.min(cols,n-row*cols);positions.push({x:count===1?W/2:left+(right-left)*(col/(count-1)),y:rows===1?(minY+bottom)/2:minY+(bottom-minY)*row/(rows-1)});}
 }
 // The enlarged character needs a clear face at the default standing position.
 // This exclusion is fixed, so tapping a star or dragging Alba never moves targets.
 const actor=scene.querySelector('#alba');
 if(actor){const aw=actor.offsetWidth,ah=actor.offsetHeight,face={left:W*.51-aw*.27,right:W*.51+aw*.27,top:H*.94-ah*.96,bottom:H*.94-ah*.51};
  const touchesFace=p=>p.x+bw/2>face.left&&p.x-bw/2<face.right&&p.y+bh/2>face.top&&p.y-bh/2<face.bottom;
  for(let i=0;i<positions.length;i++)if(touchesFace(positions[i])){const origin=positions[i],candidates=[];
   for(let x=left;x<=right+1;x+=Math.max(12,bw/4))for(let y=minY;y<=Math.max(minY,maxY)+1;y+=Math.max(12,bh/4)){const p={x,y};if(touchesFace(p)||positions.some((q,j)=>j!==i&&Math.abs(q.x-x)<bw+8&&Math.abs(q.y-y)<bh+8))continue;candidates.push(p);}
   candidates.sort((a,b)=>Math.hypot(a.x-origin.x,a.y-origin.y)-Math.hypot(b.x-origin.x,b.y-origin.y));if(candidates.length)positions[i]=candidates[0];
  }
 }
 buttons.forEach((b,i)=>{b.style.left=positions[i].x+'px';b.style.top=positions[i].y+'px';});positionActor();positionCats();
}
function positionActor(){const el=document.getElementById('alba'),scene=document.getElementById('scene');if(!el||!scene)return;const W=scene.clientWidth,H=scene.clientHeight,half=el.offsetWidth/2,height=el.offsetHeight;
 const minX=Math.min(W/2,half+4),maxX=Math.max(minX,W-half-4),minY=Math.min(H-8,height+8),maxY=Math.max(minY,H-8);
 const x=Math.max(minX,Math.min(maxX,actorPoint.x*W)),y=Math.max(minY,Math.min(maxY,actorPoint.y*H));el.style.left=x+'px';el.style.top=y+'px';}
function positionCats(){const scene=document.getElementById('scene'),alba=document.getElementById('alba');if(!scene)return;const ar=alba?.getBoundingClientRect(),sr=scene.getBoundingClientRect();const actor=ar?{left:ar.left-sr.left+ar.width*.15,right:ar.right-sr.left-ar.width*.15,top:ar.top-sr.top,bottom:ar.bottom-sr.top}:null;
 for(const el of scene.querySelectorAll('.cat-button')){if(drag?.actor===el)continue;const p=WLD.catPosition(roomId,el.dataset.name,scene.clientWidth,scene.clientHeight,el.offsetWidth,el.offsetHeight,actor);el.style.left=p.x+'px';el.style.top=p.y+'px';}
}
function stopFollowers(){cancelAnimationFrame(followerFrame);followerFrame=0;leaderHistory=[];lastFollowTick=0;}
function startFollowers(){stopFollowers();const scene=document.getElementById('scene'),actor=document.getElementById('alba');if(!scene||!actor||document.hidden)return;
 const els=[...scene.querySelectorAll('.collected-fairy')];if(!els.length)return;
 function tick(now){if(!scene.isConnected||document.hidden){stopFollowers();return;}const sr=scene.getBoundingClientRect(),ar=actor.getBoundingClientRect(),leader={t:now,x:ar.left-sr.left+ar.width/2,y:ar.top-sr.top,w:ar.width,h:ar.height};leaderHistory.push(leader);while(leaderHistory.length>2&&leaderHistory[1].t<now-700)leaderHistory.shift();
 const dt=lastFollowTick?Math.min(70,now-lastFollowTick):16;lastFollowTick=now;
 for(let i=0;i<els.length;i++){const el=els[i],conf=WLD.followerSettings(i),past=leaderHistory.filter(p=>p.t<=now-conf.delay).at(-1)||leaderHistory[0],offset=WLD.halo[i%WLD.halo.length],hw=el.offsetWidth/2,hh=el.offsetHeight/2;
  const target={x:Math.max(hw+3,Math.min(scene.clientWidth-hw-3,past.x+offset[0]*past.w)),y:Math.max(hh+3,Math.min(scene.clientHeight-hh-3,past.y+offset[1]*past.h))};let pt=followerPoints.get(el.dataset.claim);
  if(!pt||reduced()){pt={...target};followerPoints.set(el.dataset.claim,pt);}else{const a=1-Math.exp(-dt/conf.tau);pt.x+=(target.x-pt.x)*a;pt.y+=(target.y-pt.y)*a;}
  el.style.left=pt.x+'px';el.style.top=pt.y+'px';
 }
 if(!reduced())followerFrame=requestAnimationFrame(tick);
 }
 tick(performance.now());
}
function meow(){if(S?.profile.sound===false)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioContext||=new AC();audioContext.resume().catch(()=>{});const t=audioContext.currentTime,o=audioContext.createOscillator(),filter=audioContext.createBiquadFilter(),gain=audioContext.createGain();o.type='sawtooth';o.frequency.setValueAtTime(590,t);o.frequency.exponentialRampToValueAtTime(850,t+.12);o.frequency.exponentialRampToValueAtTime(380,t+.48);filter.type='lowpass';filter.frequency.setValueAtTime(1450,t);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.025,t+.055);gain.gain.exponentialRampToValueAtTime(.0001,t+.56);o.connect(filter);filter.connect(gain);gain.connect(audioContext.destination);o.start(t);o.stop(t+.58);o.onended=()=>{o.disconnect();filter.disconnect();gain.disconnect();};}catch{/* Sound is optional; no task depends on it. */}}
async function cuddleCat(name){const day=E.dayKey();if(catBusy||(S.cats[day]||[]).includes(name))return;const actor=document.getElementById('alba');if(!actor)return;catBusy=true;meow();settleActor();
 let url=null,timer=null,finish=null;try{
  if(!reduced()&&!cuddleBlobs.has(name)){const response=await fetch(A.cuddleImages[name]);if(!response.ok)throw Error('The cuddle animation could not load.');cuddleBlobs.set(name,await response.blob());}
  if(!actor.isConnected){catBusy=false;return;}
  url=reduced()?A.stillImages[name]:URL.createObjectURL(cuddleBlobs.get(name));
  const image=actor.querySelector('.alba-art');image.src=url;image.alt='Alba cuddling '+name;actor.classList.add('cuddling');actor.dataset.cuddle=name;
  const cat=document.querySelector(`.cat-button[data-name="${name}"]`);if(cat)cat.style.visibility='hidden';
  await new Promise((resolve,reject)=>{if(image.complete&&image.naturalWidth)return resolve();image.onload=resolve;image.onerror=()=>reject(Error('The cuddle animation could not play.'));});
  await commit(s=>E.findCat(s,name,day),{deferRender:true});
  await new Promise(resolve=>{finish=resolve;timer=setTimeout(resolve,1350);cuddleCleanup=()=>{clearTimeout(timer);resolve();};});
  if(actor.isConnected){image.src=reduced()?A.stillImages.alba:A.characterImages.alba;image.alt='Alba';actor.classList.remove('cuddling');delete actor.dataset.cuddle;cat?.remove();const hint=document.querySelector('.cat-hint');if(hint)hint.textContent=`Find the cats · ${(S.cats[E.dayKey()]||[]).length} of 2`;}
 }catch(err){if(actor.isConnected){const image=actor.querySelector('.alba-art');image.src=reduced()?A.stillImages.alba:A.characterImages.alba;image.alt='Alba';actor.classList.remove('cuddling');delete actor.dataset.cuddle;const cat=document.querySelector(`.cat-button[data-name="${name}"]`);if(cat)cat.style.visibility='';}throw err;}
 finally{cuddleCleanup=null;clearTimeout(timer);if(url&&url.startsWith('blob:'))URL.revokeObjectURL(url);catBusy=false;}
}
function openRooms(){const links=[['market','gift','Reward list'],['goals','star','Pinned wishes'],['week','wing','Fairy week'],['memories','album','Photo album'],['parent','check','Bedtime tidy-up'],['help','lantern','How to play']];if(S.features?.moonButtons)links.splice(3,0,['wardrobe','dress','Dress up']);openModal('Choose a room',`<nav id="room-menu" class="room-picker-list" aria-label="Rooms">${D.rooms.map(r=>button('jump',`${A.room(r.id,{thumbnail:true})}<span>${h(r.name)}</span>`,`room-jump${r.id===roomId?' active':''}`,`data-room="${r.id}" ${r.id===roomId?'aria-current="true"':''}`)).join('')}</nav><div class="drawer-links">${links.map(([act,icon,label])=>button(act,`${A.icon(icon)} ${label}`,'drawer-link')).join('')}</div>`,{drawer:true});}
function navigate(next){closeModal(false);view=next;selections.clear();render();window.scrollTo(0,0);}
function render(){if(!S)return;stopFollowers();if(cuddleCleanup)cuddleCleanup();if(fallFrame)actorPoint.y=.94;cancelActorFall();clearArrivals();resizeObserver?.disconnect();document.body.classList.toggle('home-view',view==='home');document.body.classList.toggle('calm',S.profile.calm);const scroll=window.scrollY;
 const pages={home:renderHome,missions:renderList,market:()=>renderRewards(false),goals:()=>renderRewards(true),memories:renderMemories,parent:renderParent,week:renderWeek,wardrobe:renderWardrobe};app.innerHTML=(pages[view]||renderHome)();
 if(view==='home'){layoutScene();startFollowers();resizeObserver=new ResizeObserver(layoutScene);resizeObserver.observe(document.getElementById('scene'));}
 if(view==='memories')hydratePhotos().catch(showError);if(view==='parent'&&parentTab==='data')hydrateBackupInfo().catch(showError);if(view!=='home')window.scrollTo(0,scroll);
}
async function commit(fn,options={}){if(saving)throw Error('Your last change is still saving. Please try again in a moment.');saving=true;
 try{const next=E.clone(S),result=fn(next);E.validateState(next);await DB.save(next,S.revision,options);S=next;if(!options.deferRender)render();return result;}catch(e){if(e.name==='QuotaExceededError')throw Error('This device is out of storage. Your change was not saved.');throw e;}finally{saving=false;}
}
function openModal(title,body,{compact=false,drawer=false,context=null}={}){const previous=modalRoot.querySelector('dialog');if(previous){previous.close();previous.remove();}else returnFocus=document.activeElement;
 dialogContext=context;modalRoot.innerHTML=`<dialog class="modal${compact?' compact':''}${drawer?' left-panel':''}" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${h(title)}</h2><button type="button" class="modal-close" data-action="close" aria-label="Close">${li('close')}</button></div><div class="modal-body">${body}</div><div class="error" role="alert" id="modal-error"></div></dialog>`;
 const dlg=modalRoot.querySelector('dialog');dlg.addEventListener('cancel',e=>{e.preventDefault();closeModal();});dlg.showModal();(dlg.querySelector('[autofocus]')||dlg.querySelector('.modal-close'))?.focus({preventScroll:true});
}
function closeModal(restore=true){const d=modalRoot.querySelector('dialog');if(d){d.close();d.remove();}dialogContext=null;if(restore&&returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else if(restore&&view==='home')document.querySelector('[data-action="rooms"]')?.focus({preventScroll:true});returnFocus=null;}
function showError(err){console.error(err);const el=document.getElementById('modal-error');if(el)el.textContent=err.message||'That change could not be saved.';else toast(err.message||'That change could not be saved.');}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function bigStars(n){if(n<1)return '';const count=n>10?1:n;return `<div class="award-stars" role="img" aria-label="Earn ${stars(n)}">${Array.from({length:count},()=>A.icon('star','big-star').replace('viewBox="0 0 100 100"','viewBox="18 18 64 64"')).join('')}${n>10?`<span class="star-count">× ${n}</span>`:''}</div>`;}
function openMission(id){const m=E.mission(S,id);let n=0;const isDone=done(m)&&!m.repeatable;if(!isDone)n=E.previewStars(S,id);const routine=['morning','evening'].includes(m.kind);
 let body=isDone?'<div class="notice good center">Done for today.</div>':n?bigStars(n):'';
 
 body+=button('claim',isDone?'Already done':m.repeatable&&done(m)?'I did it again!':'I did it!','primary wide mission-confirm',`data-id="${h(id)}" ${isDone?'disabled':''}`);
 openModal(m.name,body,{compact:true,context:{type:'mission',id}});
}
async function recordMission(id){const before=balance(),origin=missionOrigin(id);await commit(s=>E.record(s,id));closeModal();selections.delete(id);flyToAlba(id,origin);const gain=balance()-before;celebrate(gain);toast(gain?`Well done! ${stars(gain)} added!`:'Well done! Your mission is recorded.');}
function celebrate(n){window.FairyCelebrations.burst({stars:n,calm:!!S.profile.calm});}

function missionOrigin(id){const el=[...document.querySelectorAll('.mission-star')].find(b=>b.dataset.id===id);if(!el)return null;const r=el.querySelector('.fairy-shell').getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2};}
function clearArrivals(){for(const item of arrivalAnimations){item.animation?.cancel();item.el.remove();item.target?.classList.remove('arriving');}arrivalAnimations.clear();}
function flyToAlba(id,origin,delay=0){if(view!=='home'||!origin||S.profile.calm||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const scene=document.getElementById('scene'),target=[...scene.querySelectorAll('[data-follow-mission]')].filter(el=>el.dataset.followMission===id).at(-1);if(!target)return;
 const sr=scene.getBoundingClientRect(),r=target.getBoundingClientRect(),from={x:origin.x-sr.left,y:origin.y-sr.top},to={x:r.left-sr.left+r.width/2,y:r.top-sr.top+r.height/2};
 target.classList.add('arriving');const el=document.createElement('div');el.className='fairy-arrival';el.setAttribute('aria-hidden','true');el.innerHTML=A.taskFairy(id,'arrival-art');scene.append(el);
 const frames=[];for(let i=0;i<=24;i++){const t=i/24,x=from.x+(to.x-from.x)*t,y=from.y+(to.y-from.y)*t-Math.sin(Math.PI*t)*Math.min(95,scene.clientHeight*.13);frames.push({transform:`translate(${x}px,${y}px) translate(-50%,-50%) rotate(${Math.sin(Math.PI*t)*9}deg) scale(${1-.3*t})`});}
 const item={el,target,animation:null};arrivalAnimations.add(item);item.animation=el.animate(frames,{duration:960,delay,easing:'ease-in-out',fill:'both'});item.animation.finished.catch(()=>{}).then(()=>{target.classList.remove('arriving');el.remove();arrivalAnimations.delete(item);});
}
function cancelActorFall(){cancelAnimationFrame(fallFrame);fallFrame=0;document.getElementById('alba')?.classList.remove('falling');}
function settleActor(){cancelActorFall();const actor=document.getElementById('alba'),scene=document.getElementById('scene');if(!actor||!scene)return;
 const floor=.94,H=scene.clientHeight,from=parseFloat(actor.style.top)/H,delta=floor-from;actorPoint.y=from;
 if(Math.abs(delta)*H<2||S.profile.calm||matchMedia('(prefers-reduced-motion: reduce)').matches){actorPoint.y=floor;positionActor();return;}
 const start=performance.now(),duration=Math.max(260,Math.min(690,Math.sqrt(Math.abs(delta)*H/950)*1000));actor.classList.add('falling');
 function tick(now){if(!actor.isConnected||drag){cancelActorFall();return;}const t=Math.min(1,(now-start)/duration);actorPoint.y=from+delta*t*t;positionActor();if(t<1)fallFrame=requestAnimationFrame(tick);else{fallFrame=0;actor.classList.remove('falling');actorPoint.y=floor;positionActor();}}
 fallFrame=requestAnimationFrame(tick);
}

const groups={morning:'Morning',evening:'Evening',learning:'Learning',behaviour:'Kindness',bonus:'Extra help'};
function listNavigation(active){return `<nav class="list-navigation" aria-label="Mission and reward lists">${button('missions',`${li('list')} Mission list`,`list-tab${active==='missions'?' active':''}`,active==='missions'?'aria-current="page"':'')}${button('market',`${li('reward')} Reward list`,`list-tab${active==='market'?' active':''}`,active==='market'?'aria-current="page"':'')}</nav>`;}
function listRow(m){const complete=done(m)&&!m.repeatable,value=L.missionValue(S,m);return `<div class="mission-row${complete?' recorded':''}" data-mission-row="${h(m.id)}"><label><input type="checkbox" name="mission" value="${h(m.id)}" ${complete?'checked disabled':selections.has(m.id)?'checked':''}><span>${h(m.name)}</span></label><div class="mission-row-end">${complete?'<span class="done-text">Done</span>':''}<span class="mission-value" role="img" aria-label="${h(value.label)}" title="${h(value.label)}"><span class="value-line" aria-hidden="true">${A.icon('star','tiny-icon')}<b>${value.amount}</b></span></span></div></div>`;}
function renderList(){const choices=S.missions.filter(m=>available(m)&&(listScope==='all'||m.room===listScope));return `<main class="page list-page"><div class="page-toolbar">${goHome()}${button('oneoff',`${li('plus')} Add a one-off mission`,'secondary')}</div>${listNavigation('missions')}${listScope!=='all'?`<div class="row between"><span class="muted small">${h(D.rooms.find(r=>r.id===listScope)?.name||'This room')}</span>${button('list-all','Show every room','soft')}</div>`:''}<form data-form="list">${Object.entries(groups).map(([kind,label])=>{const ms=choices.filter(m=>m.kind===kind);return ms.length?`<section class="mission-group"><h2>${label}</h2>${ms.map(listRow).join('')}</section>`:''}).join('')}<div class="batch-footer"><button type="submit" class="primary" id="add-selected" ${selections.size?'':'disabled'}>Add selected</button></div></form></main>`;}
function showOneOff(){openModal('Add a one-off mission',`<form data-form="oneoff" class="stack"><label class="field">Mission name<input type="text" name="name" maxlength="100" placeholder="e.g. Help water the plants" required autofocus></label><label class="field">Stars to earn<input type="number" name="stars" min="1" max="10000" step="1" value="1" required></label><button class="primary wide" type="submit">Add mission</button></form>`,{compact:true});}
function rewardCard(r){const info=L.rewardInfo(S,r),pinned=S.pins.includes(r.id);return `<article class="reward-card">${button('pin',li('pin'),`pin-button${pinned?' pinned':''}`,`data-id="${h(r.id)}" aria-label="${pinned?'Unpin':'Pin'} ${h(r.name)}" aria-pressed="${pinned}"`)}<div class="reward-art">${A.icon(r.icon)}</div><h2>${h(r.name)}</h2><span class="price reward-fraction" aria-label="${info.saved} of ${stars(r.price)} saved">${A.icon('star','tiny-icon')}<b>${info.progressText}</b></span>${progress(info.saved,r.price,r.name)}${info.status?`<small class="muted">${h(info.status)}</small>`:''}<div class="reward-bottom">${button('reward',info.remaining?'Take a look':'Choose reward',info.remaining?'soft wide':'primary wide',`data-id="${h(r.id)}"`)}</div></article>`;}
function rewardListRow(r){const info=L.rewardInfo(S,r),pinned=S.pins.includes(r.id),name=r.id==='cash'?r.name+' · £1':r.name;
 return `<article class="mission-row reward-list-row${info.ready?' ready':''}" data-reward-row="${h(r.id)}" data-star-cost="${r.price}">
 <button type="button" class="reward-row-main" data-action="reward" data-id="${h(r.id)}" aria-label="${h(name)}, ${stars(r.price)}. ${h(info.progressText)}. ${h(info.limit)}">
 <span class="reward-list-art">${A.icon(r.icon)}</span><span class="reward-row-copy"><span class="row-name">${h(name)}</span>${progress(info.saved,r.price,'Progress towards '+name)}${info.status?`<span class="reward-status">${h(info.status)}</span>`:''}</span></button>
 <div class="reward-row-end">${button('pin',li('pin'),`reward-row-pin${pinned?' pinned':''}`,`data-id="${h(r.id)}" aria-label="${pinned?'Unpin':'Pin'} ${h(r.name)}" aria-pressed="${pinned}"`)}${button('reward',`<span class="value-line">${A.icon('star','tiny-icon')}<b>${info.progressText}</b></span><small>${info.remaining?'saved':info.cost===0?'free':'saved'}</small>`,'reward-cost',`data-id="${h(r.id)}" aria-label="${h(name)}: ${info.saved} of ${stars(r.price)} saved; view reward"`)}</div></article>`;
}
function renderRewardList(){const grouped=L.groupRewards(S.rewards);return `<main class="page list-page reward-list-page"><div class="page-toolbar">${goHome()}${button('edit-reward',`${li('plus')} Add a reward`,'secondary','data-id="new"')}</div>${listNavigation('market')}<div class="reward-list-summary"><span class="pill" aria-label="${stars(balance())} available">${A.icon('star','tiny-icon')} ${stars(balance())} available</span>${button('goals','Pinned wishes','soft')}</div>${grouped.map(group=>`<section class="mission-group reward-cost-group" data-reward-tier="${group.id}"><div class="reward-group-heading"><h2>${group.name}</h2><span>${group.range}</span></div>${group.rewards.map(rewardListRow).join('')}</section>`).join('')}${grouped.length?'':'<div class="empty-state"><h2>Add your first family reward.</h2><p>Use “Add a reward” to choose its name and star cost.</p></div>'}</main>`;}
function renderRewards(pinnedOnly){if(!pinnedOnly)return renderRewardList();const rewards=S.pins.map(id=>S.rewards.find(r=>r.id===id)).filter(Boolean);return `<main class="page">${pageTop('Pinned wishes','Each wish uses the same star balance. Spending stars updates all of them.',button('market','Reward list','secondary'))}<div class="reward-grid">${rewards.map(rewardCard).join('')}</div>${!rewards.length?`<div class="empty-state"><h2>Choose a wish to save for.</h2><p>Use the pin button on a reward to add it to the room.</p>${button('market','Open reward list','primary','style="margin-top:18px"')}</div>`:''}</main>`;}
function showReward(id){const r=E.reward(S,id),check=E.canRedeem(S,id),info=L.rewardInfo(S,r);openModal(r.name,`<div class="center">${A.icon(r.icon,'large-icon')}</div><div class="reward-modal-fraction" aria-label="${info.saved} of ${stars(r.price)} saved">${A.icon('star','tiny-icon')}<b>${info.progressText}</b></div>${progress(info.saved,r.price,r.name)}${info.status?`<p class="center muted">${h(info.status)}</p>`:''}${button('redeem-confirm',`Choose for ${stars(check.cost)}`,'primary wide',`data-id="${h(id)}" data-variant="single" ${check.ok?'':'disabled'}`)}${id==='cash'?button('redeem-confirm',`£5 saver · ${stars(S.config.cashSaver)}`,'secondary wide',`data-id="cash" data-variant="saver" ${E.canRedeem(S,'cash',E.dayKey(),'saver').ok?'':'disabled'}`):''}${button('pin',S.pins.includes(id)?'Unpin this wish':'Pin this wish','soft wide',`data-id="${h(id)}"`)}`,{compact:true,context:{type:'reward',id}});}
