function renderMemories(){return `<main class="page">${pageTop('Photo album','',button('photo-add',`${li('plus')} Add a photo`,'primary'))}<div class="memory-grid">${S.memories.slice().reverse().map(m=>`<article class="memory"><img data-photo="${h(m.id)}" alt="${h(m.rewardName)}"><h2>${h(m.rewardName)}</h2><small>${h(E.prettyDay(m.day))}</small><br>${button('photo-delete','Remove photo','soft',`data-id="${h(m.id)}"`)}</article>`).join('')}</div>${S.memories.length?'':`<div class="empty-state">${li('camera')}<h2>A little space for happy memories.</h2><p>Tap “Add a photo”, choose a picture, and save it here.</p></div>`}${S.redemptions.filter(r=>!S.memories.some(m=>m.receiptId===r.id)).length?`<h2 class="subheading">Rewards to remember</h2>${S.redemptions.filter(r=>!S.memories.some(m=>m.receiptId===r.id)).slice().reverse().map(r=>`<div class="mission-row"><span class="grow">${h(r.name)}</span>${button('photo-add','Add a photo','secondary',`data-receipt="${h(r.id)}"`)}</div>`).join('')}`:''}</main>`;}
function showPhoto(receiptId=''){const receipt=S.redemptions.find(r=>r.id===receiptId);openModal('Add a photo',`<form data-form="photo" class="stack"><label class="field">Choose a photo<input type="file" name="photo" accept="image/*" required></label><label class="field">Memory title<input type="text" name="title" maxlength="150" value="${h(receipt?.name||'A happy memory')}" required></label><label class="field">Date<input type="date" name="day" value="${receipt?.day||E.dayKey()}" required></label><button class="primary" type="submit">Save to photo album</button><p class="small muted">Saved here only. Keep your original photo and a backup.</p></form>`,{context:{type:'photo',receiptId}});}
async function hydratePhotos(){for(const url of photoURLs)URL.revokeObjectURL(url);photoURLs=[];for(const img of document.querySelectorAll('[data-photo]')){const blob=await DB.get('photos',img.dataset.photo);if(!img.isConnected)continue;if(blob){const url=URL.createObjectURL(blob);photoURLs.push(url);img.src=url;}else img.alt='Photo missing — restore a full backup to recover it.';}}
function renderWeek(){const w=E.weekly(S,week),best=E.bestWeek(S),current=E.weekKey(E.dayKey()),reveal=week<current||[0,5,6].includes(E.parseDay(E.dayKey()).getDay())||S.certificates[week];return `<main class="page">${pageTop('My fairy week')}<div class="row between wrap"><label class="field">Week beginning<input type="date" id="week-select" value="${week}"></label>${button('reveal',reveal?'Reveal my fairy titles':'Ready on Friday','secondary',reveal?'':'disabled')}</div><div class="stats"><div class="stat"><b>${w.total}</b><span>Stars this week</span></div><div class="stat"><b>${best.total}</b><span>My best week</span></div></div>${S.certificates[week]?`<div class="rank-grid">${Object.values(w.scores).map(s=>`<article class="rank-card">${A.icon(s.icon)}<h2>${h(s.title)}</h2><p>${h(s.name)}</p></article>`).join('')}</div>`:`<div class="empty-state">${A.icon('wing','large-icon')}<h2>Four little stories are growing.</h2><p>Come back on Friday to discover your fairy titles.</p></div>`}</main>`;}
