function renderParent(){const tabs=[['review','Bedtime tidy-up'],['missions','Edit missions'],['rewards','Edit rewards'],['settings','Settings'],['data','Backups'],['history','Star history']];const pages={review:renderReview,missions:renderMissionSettings,rewards:renderRewardSettings,settings:renderSettings,data:renderData,history:renderHistory};return `<main class="page">${pageTop('For grown-ups')}<nav class="tabs">${tabs.map(([key,label])=>button('parent-tab',label,`tab${parentTab===key?' active':''}`,`data-tab="${key}"`)).join('')}</nav>${(pages[parentTab]||renderReview)()}</main>`;}
