const configLabels={morningStars:'Morning routine stars',morningThreshold:'Morning jobs needed',eveningStars:'Evening routine stars',eveningThreshold:'Evening jobs needed',learningCap:'Daily learning star limit',behaviourBonus:'All kindnesses bonus',weeklyBonus:'Full-week star bonus',cashCap:'Weekly pocket money limit (stars)',cashSaver:'£5 saver cost (stars)'};
