function renderData(){return `<div class="stack"><section class="card stack"><h2>Ready for the iPad</h2><p class="small muted" id="install-status" role="status">${window.FSM_PREVIEW?'Mac practice copy. Install the website version on the iPad.':'Checking offline installation…'}</p><p class="small muted">A new device starts at zero. Records and photos stay on the device that created them; there is no automatic sync.</p></section><section class="card stack"><h2>A safe copy</h2><p class="small muted">Save a full backup outside this app. It includes your records and photo album photos. Local data and snapshots can be lost if the browser’s storage is cleared.</p><div class="row wrap">${button('backup',`${li('download')} Export backup`,'primary')}${button('restore','Restore a backup','secondary')}</div></section><section class="card stack"><h2>Finish testing</h2><p class="small muted">Start at zero while keeping your missions, reward choices, prices, pins, settings and photo album. Test completions, stars, reward-use history, weekly progress and found cats are cleared. Nothing resets automatically.</p>${button('clear-test-progress','Clear test progress','soft')}</section><section class="card stack"><h2>On-device snapshots</h2><div id="snapshot-list" class="small muted">Loading…</div></section><section class="card stack"><h2>Photo album</h2><p id="photo-size" class="storage-size">Loading…</p>${button('memories','Open photo album','soft')}</section></div>`;}
function showCleanStart(){openModal('Start with zero stars?',`<form data-form="clean-start" class="stack"><p>Clears test stars earned and spent, completed missions, reward-use history, weekly progress and found cats.</p><p><strong>Keep:</strong> all mission and reward definitions, prices, pins, settings and photo album photos.</p><p class="small muted">A snapshot of your current records is saved before the reset. Export a full backup first for an extra copy outside this browser.</p>${button('backup','Export a backup first','secondary')}<label class="field">Type START to confirm<input name="confirmation" autocomplete="off" autocapitalize="characters" spellcheck="false" pattern="START" required placeholder="START"></label><button type="submit" class="primary wide">Clear test progress and start at zero</button>${button('close','Cancel','soft wide')}</form>`,{compact:true,context:{type:'clean-start'}});}
let offlineInstallState='Checking offline installation…';
function updateInstallStatus(){const el=document.getElementById('install-status');if(el&&!window.FSM_PREVIEW)el.textContent=offlineInstallState;}
async function prepareOffline(){
 if(window.FSM_PREVIEW)return;
 if(!('serviceWorker' in navigator)||!isSecureContext){offlineInstallState='Open the hosted HTTPS website in Safari to install offline support.';updateInstallStatus();return;}
 try{
  const reg=await navigator.serviceWorker.register('./sw.js');
  const showWorker=worker=>{
   if(!worker)return;
   const check=()=>{if(worker.state==='activated'){offlineInstallState='Offline ready — the app and all artwork have been saved on this device.';updateInstallStatus();}else if(worker.state==='redundant'){offlineInstallState='Offline installation did not finish. Stay online, sign in to the private website and reopen the app.';updateInstallStatus();}};
   worker.addEventListener('statechange',check);check();
  };
  reg.addEventListener('updatefound',()=>showWorker(reg.installing));
  showWorker(reg.installing||reg.waiting||reg.active);
  navigator.serviceWorker.ready.then(()=>{offlineInstallState='Offline ready — the app and all artwork have been saved on this device.';updateInstallStatus();});
 }catch(err){offlineInstallState='Offline installation did not finish. Stay online and reopen the app.';updateInstallStatus();console.warn('Offline setup',err);}
}
async function hydrateBackupInfo(){updateInstallStatus();const snaps=await DB.snapshotList(),list=document.getElementById('snapshot-list');if(list)list.innerHTML=snaps.length?snaps.map(s=>`<div class="history-row"><span>${h(new Date(s.value.at).toLocaleString('en-GB'))}</span>${button('snapshot','Restore','soft',`data-key="${h(s.key)}"`)}</div>`).join(''):'Daily snapshots appear after you start using the app.';const bytes=await DB.photoBytes(),size=document.getElementById('photo-size');if(size)size.textContent=`${S.memories.length} photos · ${(bytes/1024/1024).toFixed(1)} MB`;}
function renderHistory(){return `<h2 class="subheading">Stars earned</h2>${S.ledger.slice().reverse().map(a=>`<div class="history-row"><div>${h(a.name)}<br><small>${h(E.prettyDay(a.day))}</small></div><b>+${a.stars}</b></div>`).join('')}<h2 class="subheading">Rewards chosen</h2>${S.redemptions.slice().reverse().map(r=>`<div class="history-row"><div>${h(r.name)}<br><small>${h(E.prettyDay(r.day))} · ${stars(r.cost)}</small></div>${button('undo-spend','Undo spend','soft',`data-id="${h(r.id)}"`)}</div>`).join('')}`;}
